import React, { useMemo, useState } from 'react';
import {
  Box,
  Button,
  Chip,
  CircularProgress,
  Grid,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { Article as ArticleIcon } from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import { usePublicArticles } from '../hooks/usePublicArticles';
import { BLOG_CATEGORY_LABELS, type BlogArticleCategory } from '../constants/blogArticles';
import MarketingHeading from './shared/MarketingHeading';
import { ArticleCard } from './marketing/ArticlesTeaserSection';

const CATEGORY_OPTIONS: Array<BlogArticleCategory | 'all'> = [
  'all',
  'sustainability',
  'compliance',
  'msme',
  'product',
  'industry',
  'general',
];

const InsightsPage: React.FC = () => {
  const theme = useTheme();
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState<BlogArticleCategory | 'all'>('all');
  const [page, setPage] = useState(1);

  const queryCategory = category === 'all' ? undefined : category;
  const { articles, pagination, loading, error, refresh } = usePublicArticles({
    page,
    limit: 12,
    category: queryCategory,
    search: search.trim() || undefined,
  });

  const totalPages = pagination?.pages || 1;

  const categoryChips = useMemo(() => CATEGORY_OPTIONS.map((value) => (
    <Chip
      key={value}
      label={value === 'all' ? 'All topics' : BLOG_CATEGORY_LABELS[value]}
      color={category === value ? 'primary' : 'default'}
      variant={category === value ? 'filled' : 'outlined'}
      onClick={() => {
        setCategory(value);
        setPage(1);
      }}
      sx={{ fontWeight: 600 }}
    />
  )), [category]);

  return (
    <Box sx={{ maxWidth: 1080, mx: 'auto', py: { xs: 2, md: 3 } }}>
      <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 2 }}>
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            width: 48,
            height: 48,
            borderRadius: 2,
            bgcolor: alpha(theme.palette.primary.main, 0.12),
            color: 'primary.main',
          }}
        >
          <ArticleIcon />
        </Box>
        <Box>
          <MarketingHeading level="h1">
            Insights &amp; articles
          </MarketingHeading>
          <Typography variant="body1" color="text.secondary" sx={{ lineHeight: 1.7 }}>
            Carbon intelligence, compliance, and MSME sustainability guidance.
          </Typography>
        </Box>
      </Stack>

      <Stack direction={{ xs: 'column', md: 'row' }} spacing={2} sx={{ mb: 3 }}>
        <TextField
          label="Search articles"
          value={search}
          onChange={(event) => {
            setSearch(event.target.value);
            setPage(1);
          }}
          size="small"
          fullWidth
        />
        <Button component={RouterLink} to="/" variant="outlined">
          Back to home
        </Button>
      </Stack>

      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 3 }}>
        {categoryChips}
      </Stack>

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
          <CircularProgress />
        </Box>
      ) : error ? (
        <Stack spacing={1.5} alignItems="flex-start" sx={{ py: 2 }}>
          <Typography color="error">{error}</Typography>
          <Button variant="contained" onClick={() => { void refresh(); }}>
            Retry
          </Button>
        </Stack>
      ) : articles.length === 0 ? (
        <Typography color="text.secondary">
          {search.trim()
            ? `No articles match “${search.trim()}”. Clear the search to see the catalogue again.`
            : 'No published articles yet. Check back soon for sustainability insights.'}
        </Typography>
      ) : (
        <>
          <Grid container spacing={2.5}>
            {articles.map((article) => (
              <Grid item xs={12} sm={6} md={4} key={article.id}>
                <ArticleCard article={article} />
              </Grid>
            ))}
          </Grid>
          {totalPages > 1 ? (
            <Stack direction="row" spacing={1.5} justifyContent="center" sx={{ mt: 4 }}>
              <Button
                variant="outlined"
                disabled={page <= 1}
                onClick={() => setPage((current) => Math.max(1, current - 1))}
              >
                Previous
              </Button>
              <Chip label={`Page ${page} of ${totalPages}`} variant="outlined" />
              <Button
                variant="outlined"
                disabled={page >= totalPages}
                onClick={() => setPage((current) => current + 1)}
              >
                Next
              </Button>
            </Stack>
          ) : null}
        </>
      )}
    </Box>
  );
};

export default InsightsPage;
